options.afterRender:
(function() {
function getVal(row, attrName, cellIdx) {
  let val = parseFloat(row.getAttribute(attrName));
  if (isNaN(val) && row.cells && row.cells[cellIdx]) {
    const txt = row.cells[cellIdx].innerText.trim().replace('+', '').replace(/,/g, '');
    val = parseFloat(txt);
  }
  return isNaN(val) ? 0 : val;
}

function renderDeltaHTML(pos, neg) {
  if (pos === 0 && neg === 0) return '<span class="delta-pill delta-zero">0</span>';
  let html = '<div style="display: inline-flex; align-items: center; justify-content: center; gap: 6px; flex-wrap: nowrap;">';
  if (pos > 0) html += '<span class="delta-pill delta-pos">+' + Math.round(pos).toLocaleString() + '</span>';
  if (neg < 0) html += '<span class="delta-pill delta-neg">' + Math.round(neg).toLocaleString() + '</span>';
  html += '</div>';
  return html;
}

function recalculateMonthFooter(cnt) {
  const visibleRows = cnt.querySelectorAll('tbody tr:not(.row-hidden)');
  let sumMonthPlan = 0, sumPlan = 0, sumCuring = 0, sumScrap = 0, sumNet = 0, sumDel = 0, sumQueue = 0;
  let posDeltaCur = 0, negDeltaCur = 0, posDeltaDel = 0, negDeltaDel = 0;

  visibleRows.forEach(row => {
    sumMonthPlan += getVal(row, 'data-month-plan', 6);
    sumPlan += getVal(row, 'data-plan', 7);
    sumCuring += getVal(row, 'data-curing', 8);

    const dCur = getVal(row, 'data-delta-curing', 9);
    if (dCur > 0) posDeltaCur += dCur;
    if (dCur < 0) negDeltaCur += dCur;

    sumScrap += getVal(row, 'data-scrap', 11);
    sumNet += getVal(row, 'data-net', 12);
    sumDel += getVal(row, 'data-delivery', 13);

    const dDel = getVal(row, 'data-delta-del', 14);
    if (dDel > 0) posDeltaDel += dDel;
    if (dDel < 0) negDeltaDel += dDel;

    sumQueue += getVal(row, 'data-queue', 16);
  });

  const foot = cnt.querySelector('tfoot');
  if (foot) {
    const totMonthPlan = foot.querySelector('.tot-month-plan');
    if (totMonthPlan) totMonthPlan.innerText = sumMonthPlan > 0 ? Math.round(sumMonthPlan).toLocaleString() : '0';

    const totPlan = foot.querySelector('.tot-plan');
    if (totPlan) totPlan.innerText = sumPlan > 0 ? Math.round(sumPlan).toLocaleString() : '0';

    const totCuring = foot.querySelector('.tot-curing');
    if (totCuring) totCuring.innerText = sumCuring > 0 ? Math.round(sumCuring).toLocaleString() : '0';

    const totScrap = foot.querySelector('.tot-scrap');
    if (totScrap) totScrap.innerText = sumScrap > 0 ? Math.round(sumScrap).toLocaleString() : '0';

    const totNet = foot.querySelector('.tot-net');
    if (totNet) totNet.innerText = sumNet > 0 ? Math.round(sumNet).toLocaleString() : '0';

    const totDel = foot.querySelector('.tot-del');
    if (totDel) totDel.innerText = sumDel > 0 ? Math.round(sumDel).toLocaleString() : '0';

    const totQueue = foot.querySelector('.tot-queue');
    if (totQueue) totQueue.innerText = sumQueue > 0 ? Math.round(sumQueue).toLocaleString() : '0';

    const totDCur = foot.querySelector('.tot-delta-curing');
    if (totDCur) totDCur.innerHTML = renderDeltaHTML(posDeltaCur, negDeltaCur);

    const totDDel = foot.querySelector('.tot-delta-del');
    if (totDDel) totDDel.innerHTML = renderDeltaHTML(posDeltaDel, negDeltaDel);
  }
}

function filterMonthRows(container) {
  const activePills = Array.from(container.querySelectorAll('.fp-pill.active'));
  const activeFilters = activePills.map(p => p.getAttribute('data-filter')).filter(f => f && f !== 'all');

  const searchInput = container.querySelector('.row-search-input');
  const query = searchInput ? searchInput.value.toLowerCase().trim() : '';

  const rows = container.querySelectorAll('tbody tr');
  let visibleCount = 0;

  rows.forEach(row => {
    let hide = false;
    const planVal     = getVal(row, 'data-plan', 7);
    const deltaCuring = getVal(row, 'data-delta-curing', 9);
    const deltaDel    = getVal(row, 'data-delta-del', 14);
    const queueVal    = getVal(row, 'data-queue', 16);
    const alertVal    = (row.getAttribute('data-alert') || (row.cells && row.cells[17] ? row.cells[17].innerText.trim() : '')).toUpperCase();

    if (activeFilters.length > 0) {
      const isStop       = alertVal.includes('STOP');
      const isProduce    = alertVal.includes('PRODUCE');
      const isPlanned    = planVal > 0;
      const isCurDeficit = deltaCuring < 0;
      const isDelDeficit = deltaDel < 0;
      const isQueuePos   = queueVal > 0;

      // Strict AND (compound SQL/Excel condition):
      // Alert column check (STOP / PRODUCE)
      const hasStop = activeFilters.includes('stop');
      const hasProduce = activeFilters.includes('produce');
      if (hasStop && hasProduce) {
        if (!isStop && !isProduce) hide = true;
      } else if (hasStop) {
        if (!isStop) hide = true;
      } else if (hasProduce) {
        if (!isProduce) hide = true;
      }

      // Planned column check (WHERE plan_qty > 0)
      if (!hide && activeFilters.includes('planned')) {
        if (!isPlanned) hide = true;
      }

      // Curing Deficit check (WHERE delta_curing < 0)
      if (!hide && activeFilters.includes('cur-neg')) {
        if (!isCurDeficit) hide = true;
      }

      // Delivery Deficit check (WHERE delta_delivery < 0)
      if (!hide && activeFilters.includes('del-neg')) {
        if (!isDelDeficit) hide = true;
      }

      // Inspection Queue check (WHERE inspection_queue > 0)
      if (!hide && activeFilters.includes('insp-queue')) {
        if (!isQueuePos) hide = true;
      }
    }

    if (!hide && query) {
      const text = row.innerText.toLowerCase();
      if (!text.includes(query)) {
        hide = true;
      }
    }

    if (hide) {
      row.classList.add('row-hidden');
    } else {
      row.classList.remove('row-hidden');
      visibleCount++;
    }
  });

  const countBadge = container.querySelector('.row-count-badge');
  if (countBadge) {
    countBadge.innerText = visibleCount + ' / ' + rows.length;
  }

  recalculateMonthFooter(container);
}

function bindMonthContainer(container) {
  if (!container) return;

  filterMonthRows(container);

  container.onclick = function(e) {
    const pill = e.target.closest('.fp-pill');
    if (!pill) return;
    e.stopPropagation();

    const filterType = pill.getAttribute('data-filter');
    const allPills = container.querySelectorAll('.fp-pill');
    const allRowsPill = container.querySelector('.fp-pill[data-filter="all"]');

    if (filterType === 'all') {
      allPills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
    } else {
      pill.classList.toggle('active');
      if (allRowsPill) allRowsPill.classList.remove('active');

      const anyActive = Array.from(allPills).some(p => p.getAttribute('data-filter') !== 'all' && p.classList.contains('active'));
      if (!anyActive && allRowsPill) {
        allRowsPill.classList.add('active');
      }
    }

    filterMonthRows(container);
  };

  const searchInput = container.querySelector('.row-search-input');
  if (searchInput) {
    searchInput.oninput = function(e) {
      e.stopPropagation();
      filterMonthRows(container);
    };
    searchInput.onkeyup = function(e) {
      e.stopPropagation();
      filterMonthRows(container);
    };
  }
}

const containers = document.querySelectorAll('.dt-container-month');
containers.forEach(bindMonthContainer);
})();

options.helpers:
handlebars.registerHelper('sumField', function(data, fieldName) {
  if (!Array.isArray(data)) return 0;
  return data.reduce(function(acc, row) {
    var val = parseFloat(row[fieldName]);
    return acc + (isNaN(val) ? 0 : val);
  }, 0);
});

handlebars.registerHelper('formatSum', function(val) {
  if (isNaN(val) || val === 0) return '0';
  return Math.round(val).toLocaleString();
});

handlebars.registerHelper('sumPositive', function(data, fieldName) {
  if (!Array.isArray(data)) return 0;
  return data.reduce(function(acc, row) {
    var val = parseFloat(row[fieldName]);
    return acc + (!isNaN(val) && val > 0 ? val : 0);
  }, 0);
});

handlebars.registerHelper('sumNegative', function(data, fieldName) {
  if (!Array.isArray(data)) return 0;
  return data.reduce(function(acc, row) {
    var val = parseFloat(row[fieldName]);
    return acc + (!isNaN(val) && val < 0 ? val : 0);
  }, 0);
});

handlebars.registerHelper('renderDeltaSum', function(data, fieldName) {
  if (!Array.isArray(data)) return '-';
  var pos = 0, neg = 0;
  data.forEach(function(row) {
    var val = parseFloat(row[fieldName]);
    if (!isNaN(val)) {
      if (val > 0) pos += val;
      if (val < 0) neg += val;
    }
  });
  if (pos === 0 && neg === 0) {
    return new handlebars.SafeString('<span class="delta-pill delta-zero">0</span>');
  }
  var html = '<div style="display: inline-flex; align-items: center; justify-content: center; gap: 6px; flex-wrap: nowrap;">';
  if (pos > 0) {
    html += '<span class="delta-pill delta-pos">+' + Math.round(pos).toLocaleString() + '</span>';
  }
  if (neg < 0) {
    html += '<span class="delta-pill delta-neg">' + Math.round(neg).toLocaleString() + '</span>';
  }
  html += '</div>';
  return new handlebars.SafeString(html);
});

