function getActiveShifts(container) {
  const activeShiftPills = Array.from(container.querySelectorAll('.shift-pill.active'));
  const vals = activeShiftPills.map(p => p.getAttribute('data-shift'));
  if (vals.includes('all') || vals.length === 0 || vals.length === 3) {
    return ['1', '2', '3'];
  }
  return vals;
}

function recomputeShiftMetrics(container, activeShifts) {
  const isAll = activeShifts.length === 3;
  const numActive = isAll ? 3 : activeShifts.length;
  const ratio = numActive / 3.0;

  const rows = container.querySelectorAll('tbody tr');
  rows.forEach(row => {
    const dayPlan = parseFloat(row.getAttribute('data-day-plan')) || 0;
    const dayDel = parseFloat(row.getAttribute('data-day-del')) || 0;

    // Shift Target
    const target = Math.round(dayPlan * ratio);

    // Shift Curing
    let curing = 0;
    if (isAll || activeShifts.includes('1')) curing += (parseFloat(row.getAttribute('data-cured-s1')) || 0);
    if (isAll || activeShifts.includes('2')) curing += (parseFloat(row.getAttribute('data-cured-s2')) || 0);
    if (isAll || activeShifts.includes('3')) curing += (parseFloat(row.getAttribute('data-cured-s3')) || 0);

    // Shift Scrap
    let scrap = 0;
    if (isAll || activeShifts.includes('1')) scrap += (parseFloat(row.getAttribute('data-scrap-s1')) || 0);
    if (isAll || activeShifts.includes('2')) scrap += (parseFloat(row.getAttribute('data-scrap-s2')) || 0);
    if (isAll || activeShifts.includes('3')) scrap += (parseFloat(row.getAttribute('data-scrap-s3')) || 0);

    // Net Cured
    const net = curing - scrap;

    // Shift Delivery
    const del = Math.round(dayDel * ratio);

    // Deltas
    const deltaCur = curing - target;
    const deltaDel = del - target;

    // CI
    let ciCur = '-';
    if (target > 0) {
      const pct = Math.min(100, Math.round((Math.max(0, net) / target) * 1000) / 10).toFixed(1);
      ciCur = pct + '%';
    }

    let ciDel = '-';
    if (target > 0) {
      const pct = Math.min(100, Math.round((del / target) * 1000) / 10).toFixed(1);
      ciDel = pct + '%';
    }

    // Inspection Queue
    const queue = Math.max(0, net - del);

    // Update row attributes
    row.setAttribute('data-target', target);
    row.setAttribute('data-plan', target);
    row.setAttribute('data-curing', curing);
    row.setAttribute('data-delta-curing', deltaCur);
    row.setAttribute('data-scrap', scrap);
    row.setAttribute('data-net', net);
    row.setAttribute('data-delivery', del);
    row.setAttribute('data-delta-del', deltaDel);
    row.setAttribute('data-queue', queue);

    // Update cell elements
    if (row.cells && row.cells[7]) {
      row.cells[7].innerHTML = target > 0 ? '<span class="val-plan">' + target.toLocaleString() + '</span>' : '<span class="val-zero">0</span>';
    }
    if (row.cells && row.cells[8]) {
      row.cells[8].innerHTML = curing > 0 ? '<span class="val-curing">' + curing.toLocaleString() + '</span>' : '<span class="val-zero">0</span>';
    }
    if (row.cells && row.cells[9]) {
      if (deltaCur > 0) {
        row.cells[9].innerHTML = '<span class="delta-pill delta-pos">+' + deltaCur.toLocaleString() + '</span>';
      } else if (deltaCur < 0) {
        row.cells[9].innerHTML = '<span class="delta-pill delta-neg">' + deltaCur.toLocaleString() + '</span>';
      } else {
        row.cells[9].innerHTML = '<span class="delta-pill delta-zero">0</span>';
      }
    }
    if (row.cells && row.cells[10]) {
      row.cells[10].innerText = ciCur;
    }
    if (row.cells && row.cells[11]) {
      row.cells[11].innerHTML = scrap > 0 ? '<span class="scrap-warn">' + scrap.toLocaleString() + '</span>' : '<span class="val-zero">0</span>';
    }
    if (row.cells && row.cells[12]) {
      row.cells[12].innerHTML = net > 0 ? '<span class="val-active">' + net.toLocaleString() + '</span>' : '<span class="val-zero">0</span>';
    }
    if (row.cells && row.cells[13]) {
      row.cells[13].innerHTML = del > 0 ? '<span class="val-delivery">' + del.toLocaleString() + '</span>' : '<span class="val-zero">0</span>';
    }
    if (row.cells && row.cells[14]) {
      if (deltaDel > 0) {
        row.cells[14].innerHTML = '<span class="delta-pill delta-pos">+' + deltaDel.toLocaleString() + '</span>';
      } else if (deltaDel < 0) {
        row.cells[14].innerHTML = '<span class="delta-pill delta-neg">' + deltaDel.toLocaleString() + '</span>';
      } else {
        row.cells[14].innerHTML = '<span class="delta-pill delta-zero">0</span>';
      }
    }
    if (row.cells && row.cells[15]) {
      row.cells[15].innerText = ciDel;
    }
    if (row.cells && row.cells[16]) {
      row.cells[16].innerHTML = queue > 0 ? '<span class="val-queue">' + queue.toLocaleString() + '</span>' : '<span class="val-zero">0</span>';
    }
  });
}

function filterShiftRows(container) {
  const activeDeltaPills = Array.from(container.querySelectorAll('.fp-pill:not(.shift-pill).active'));
  const activeFilters = activeDeltaPills.map(p => p.getAttribute('data-filter')).filter(f => f && f !== 'all');

  const searchInput = container.querySelector('.row-search-input');
  const query = searchInput ? searchInput.value.toLowerCase().trim() : '';

  const rows = container.querySelectorAll('tbody tr');
  let visibleCount = 0;

  rows.forEach(row => {
    let hide = false;
    const planVal     = getVal(row, 'data-target', 7);
    const deltaCuring = getVal(row, 'data-delta-curing', 9);
    const deltaDel    = getVal(row, 'data-delta-del', 14);
    const queueVal    = getVal(row, 'data-queue', 16);
    const alertVal    = (row.getAttribute('data-alert') || (row.cells && row.cells[17] ? row.cells[17].innerText.trim() : '')).toUpperCase();

    if (activeFilters.length > 0) {
      const isStop       = alertVal.includes('STOP');
      const isProduce    = alertVal.includes('PRODUCE');
      const isPlanned    = planVal > 0;
      const isCurDeficit = deltaCuring < 0;
      const isDelDeficit = deltaDel < 0;
      const isQueuePos   = queueVal > 0;

      const hasStop = activeFilters.includes('stop');
      const hasProduce = activeFilters.includes('produce');
      if (hasStop && hasProduce) {
        if (!isStop && !isProduce) hide = true;
      } else if (hasStop) {
        if (!isStop) hide = true;
      } else if (hasProduce) {
        if (!isProduce) hide = true;
      }

      if (!hide && activeFilters.includes('planned')) {
        if (!isPlanned) hide = true;
      }

      if (!hide && activeFilters.includes('cur-neg')) {
        if (!isCurDeficit) hide = true;
      }

      if (!hide && activeFilters.includes('del-neg')) {
        if (!isDelDeficit) hide = true;
      }

      // Inspection Queue check (WHERE inspection_queue > 0)
      if (!hide && activeFilters.includes('insp-queue')) {
        if (!isQueuePos) hide = true;
      }
    }

    if (!hide && query) {
      const text = row.innerText.toLowerCase();
      if (!text.includes(query)) {
        hide = true;
      }
    }

    if (hide) {
      row.classList.add('row-hidden');
    } else {
      row.classList.remove('row-hidden');
      visibleCount++;
    }
  });

  const countBadge = container.querySelector('.row-count-badge');
  if (countBadge) {
    countBadge.innerText = visibleCount + ' / ' + rows.length;
  }

  recalculateShiftFooter(container);
}

function bindShiftContainer(container) {
  if (!container) return;

  filterShiftRows(container);

  container.onclick = function(e) {
    const pill = e.target.closest('.fp-pill');
    if (!pill) return;
    e.stopPropagation();

    // 1. Shift Pill Click Handler (Multi-Select)
    if (pill.classList.contains('shift-pill')) {
      const shiftVal = pill.getAttribute('data-shift');
      const allShiftPills = container.querySelectorAll('.shift-pill');
      const allPill = container.querySelector('.shift-pill[data-shift="all"]');

      if (shiftVal === 'all') {
        allShiftPills.forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
      } else {
        pill.classList.toggle('active');
        if (allPill) allPill.classList.remove('active');

        const activeSpecific = Array.from(allShiftPills).filter(p => p.getAttribute('data-shift') !== 'all' && p.classList.contains('active'));
        if (activeSpecific.length === 0 || activeSpecific.length === 3) {
          allShiftPills.forEach(p => p.classList.remove('active'));
          if (allPill) allPill.classList.add('active');
        }
      }

      const activeShifts = getActiveShifts(container);
      recomputeShiftMetrics(container, activeShifts);
      filterShiftRows(container);
      return;
    }

    // 2. Delta Filter Pill Click Handler (Existing Multi-Select)
    const filterType = pill.getAttribute('data-filter');
    const allDeltaPills = container.querySelectorAll('.fp-pill:not(.shift-pill)');
    const allRowsPill = container.querySelector('.fp-pill[data-filter="all"]');

    if (filterType === 'all') {
      allDeltaPills.forEach(p => p.classList.remove('active'));
      pill.classList.add('active');
    } else {
      pill.classList.toggle('active');
      if (allRowsPill) allRowsPill.classList.remove('active');

      const anyActive = Array.from(allDeltaPills).some(p => p.getAttribute('data-filter') !== 'all' && p.classList.contains('active'));
      if (!anyActive && allRowsPill) {
        allRowsPill.classList.add('active');
      }
    }

    filterShiftRows(container);
  };

  const searchInput = container.querySelector('.row-search-input');
  if (searchInput) {
    searchInput.oninput = function(e) {
      e.stopPropagation();
      filterShiftRows(container);
    };
    searchInput.onkeyup = function(e) {
      e.stopPropagation();
      filterShiftRows(container);
    };
  }
}

const containers = document.querySelectorAll('.dt-container-shift');
containers.forEach(bindShiftContainer);
})();

