  if (pos > 0) {
    html += '<span class="delta-pill delta-pos">+' + Math.round(pos).toLocaleString() + '</span>';
  }
  if (neg < 0) {
    html += '<span class="delta-pill delta-neg">' + Math.round(neg).toLocaleString() + '</span>';
  }
  html += '</div>';
